import * as M from './model.js';
import {listGames,getGame,putGame,openDB,getTeamLink,putTeamLink,deleteGame} from './db.js';
import {prepareOffline} from './prepare.js';
import {prepareReportPrint,clearReportPrint} from './print.js';
let teamLink=null,current=null,games=[],work=Promise.resolve(),busy=false,ready=false,editor=null,toastTimer,logPage=0,logSide='all';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),button=(label,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const field=(label,id,value='',type='text',extra='')=>`<label>${label}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const periodName=g=>g.gameFormat==='Halves'?(g.period<=2?'Half '+g.period:'OT '+(g.period-2)):(g.period<=4?'Quarter '+g.period:'OT '+(g.period-4));
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function error(e){$('storageError').hidden=false;$('storageError').textContent='Change not saved: '+(e.message||e)+'. Your previous saved game is intact. Keep the app open and export a backup.';toast(e.message||String(e));}
function modal(title,html,kicker='CoachIQ GameDay'){ $('modalTitle').textContent=title;$('modalKicker').textContent=kicker;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function close(){if($('modal').open)$('modal').close();editor=null;}
function status(){ $('connectionStatus').textContent=busy?'Saving on this iPad…':!navigator.onLine?'Offline · device saved':'Online · device saved';}
async function refresh(){games=await listGames();render();}
function mutate(command){work=work.then(async()=>{if(!current)throw Error('Open a game first.');busy=true;status();const previous=current,next=M.clone(previous);command(next);const saved=await putGame(next,previous.revision);current=saved;$('storageError').hidden=true;games=await listGames();render();return saved;}).catch(e=>{error(e);return null;}).finally(()=>{busy=false;status();});return work;}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Download requested. Confirm the file appears in Files / Downloads.');}
function render(){status();if(current)renderLive();else renderHome();const chips=document.querySelector("#currentPossessionBar .possession-chips");if(chips)chips.scrollTop=chips.scrollHeight;}
function renderHome(){ $('main').innerHTML=`<div class="page-heading"><div><span class="eyebrow">Courtside workspace</span><h1>Your game. Ready when you are.</h1><p>Single-iPad tracking, saved locally. Reports work without a connection.</p></div><div class="actions">${button('CoachIQ team link','team-link')}${button('Import file','import')}${button('+ New game','new','primary')}</div></div><section class="surface" style="margin-bottom:18px"><span class="eyebrow">CoachIQ team names</span><h3>${teamLink?esc(teamLink.schoolName||'Teams linked on this iPad'):'Link your CoachIQ teams'}</h3><p class="field-note">${teamLink?teamLink.teams.map(esc).join(' · ')+' · Season '+esc(teamLink.season||'unspecified'):'Import a team-link file from CoachIQ to choose the exact team name and avoid result-import mismatches.'}</p><small>Saved copy of your team settings; refresh the link file when CoachIQ teams or the season change.</small></section><section class="surface readiness ${ready?'ready':''}"><div><span class="eyebrow">${ready?'App saved for offline opening':'First-time setup'}</span><h3>${ready?'This browser has the offline app files.':'Prepare this iPad before game day.'}</h3><p>${ready?'Add to Home Screen, then complete the airplane-mode close/reopen test on this iPad. A browser check is not a hardware certification.':'Connect to the internet, prepare the offline files, then install to your Home Screen. Your game data stays on this device.'}</p></div>${button(ready?'Check again':'Prepare for offline','prepare',ready?'':'primary')}</section><div class="section-heading"><h2>Saved on this iPad</h2><span class="muted">${games.length} game${games.length===1?'':'s'}</span></div>${games.length?'<div class="game-grid">'+games.map(g=>`<article class="surface game-card"><div><div><h3>${esc(g.team)} vs. ${esc(g.opponent)}</h3><small>${esc(g.gameDate)} · ${esc(g.status==='completed'?'Final '+g.finalScore.our+'–'+g.finalScore.opponent:periodName(g))}</small></div><span class="pill ${g.status==='completed'?'completed':''}">${g.transferLocked?'EXPORTED':g.status==='live'?'LIVE':'FINAL'}</span></div><div class="actions">${button(g.status==='live'?'Resume game':'Open report','open','primary',`data-id="${esc(g.id)}"`)}${button('Delete','delete-game','danger',`data-id="${esc(g.id)}" aria-label="Delete ${esc(g.team)} vs. ${esc(g.opponent)} from this iPad"`)}</div></article>`).join('')+'</div>':`<section class="surface empty"><span class="eyebrow">A clean start</span><h2>Bring your next matchup here.</h2><p>Create a game with rosters, or import a preparation file from CoachIQ. Once saved here, the game and its reports stay available offline.</p>${button('Create your first game','new','primary')}</section>`}<section class="surface" style="margin-top:24px"><h3>Start with these three steps</h3><div class="step-grid"><article><b>01 · PREPARE</b><p>Prepare the offline app and add it to your iPad Home Screen while online.</p></article><article><b>02 · TEST</b><p>Create a practice game. In airplane mode, record plays, close and reopen, and check every saved play.</p></article><article><b>03 · KEEP A COPY</b><p>Export a backup each period. After the game, export the locked result and import it into CoachIQ.</p></article></div></section><p class="footer-note">GameDay ${M.VERSION} · Local game-day pilot. This is separate from your existing CoachIQ app. Exports/imports are manual; no automatic background sync is claimed. Private browsing, clearing website data or deleting the app can remove local records. Keep backups in Files.</p>`;}
function eventLabel(event){const names={...Object.fromEntries(M.TAGS),foulRetained:'Foul · keeps ball',foulFreeThrows:'Foul → FTs',freeThrows:'Free throws',ftMade:'FT made',ftMiss:'FT missed',made1:'Scored 1',made2:'Made 2',made3:'Made 3',andOne:'And-one',miss2:'Missed 2',miss3:'Missed 3'};return(event.type==='customTag'?event.label:names[event.type]||event.type)+(event.jersey?' #'+event.jersey:'');}
function draftDescription(d){return(d.playEvents||[]).map(eventLabel).concat(d.transition?['Transition']:[],d.rightHandDrive?['Right-hand drive']:[]).join(' → ')||'No tags yet · half court';}
function possessionBar(g){const d=g.draft,hasEvents=d.playEvents.length||d.transition||d.rightHandDrive,last=M.activeLog(g).at(-1),showLast=!hasEvents&&last,item=showLast?last:d,ft=M.freeThrowSummary(item),side=item.teamSide==='offense'?'Offense':'Defense',chips=(item.playEvents||[]).map(e=>`<span class="possession-chip ${e.type==='ftMade'?'made':e.type==='ftMiss'?'missed':''}">${esc(eventLabel(e))}</span>`).concat(item.transition?['<span class="possession-chip">Transition</span>']:[],item.rightHandDrive?['<span class="possession-chip">Right-hand drive</span>']:[]);return `<section id="currentPossessionBar" class="possession-bar" role="status" aria-live="polite"><div><strong>${showLast?'Last possession saved':'Current possession'} · ${side}</strong><b>${showLast?item.points+' point'+(item.points===1?'':'s'):M.hasFreeThrows(d)?ft.points+' point'+(ft.points===1?'':'s')+' pending':'Not saved yet'}</b></div><div class="possession-chips">${chips.join('')||'<small>No tags yet. Tap what mattered, then the outcome.</small>'}</div><small>${showLast?'Now tracking '+(d.teamSide==='offense'?'our offense':'our defense')+'.':ft.attempted?ft.made+'/'+ft.attempted+' free throws made. Finish only when the possession is over.':'Each tap stays with this possession. Undo tag removes the last selection.'}</small></section>`;}
function freeThrowControls(g){const d=g.draft,ft=M.freeThrowSummary(d);if(!M.hasFreeThrows(d))return `<div class="free-throw-entry">${button('Foul → keeps ball','foul-retained')}${button('Foul → FTs','foul-fts')}${button('Free throws','ft-start')}<small>A foul does not automatically end the possession. Record FT attempts if awarded, or keep tracking the inbound play.</small></div>`;return `<section class="free-throw-panel"><div class="section-heading"><h3>Free throws · ${ft.made}/${ft.attempted}</h3><strong>${ft.points} total points</strong></div><div class="free-throw-buttons">${button('FT made','ft-made','mint')}${button('FT missed','ft-missed')}</div><p class="field-note">Tap once per attempt. A miss keeps this possession open. Add OREB if the offense gets the rebound, then continue the play.</p><div class="actions">${button('Foul → keeps ball','foul-retained')}${button('Another foul → FTs','foul-fts')}</div><details><summary>Include a made basket / putback</summary><div class="actions">${button('+ Made 2','ft-basket','', 'data-points="2"')}${button('+ Made 3','ft-basket','', 'data-points="3"')}</div><small>Add the basket for an and-one, or a putback after a missed FT. Use Undo tag for an accidental tap.</small></details><div class="outcomes ft-outcomes">${button('End possession · '+ft.points+' point'+(ft.points===1?'':'s'),'ft-finish','primary',!ft.attempted?'disabled':'')}${button(d.teamSide==='offense'?'Turnover':'Forced turnover','turnover','danger',ft.points?'disabled':'')}</div></section>`;}

function renderLive(){const g=current,{analytics:a,score}=M.totals(g),review=M.gameReport(g).review,d=g.draft,live=g.status==='live'&&!g.transferLocked,roster=d.teamSide==='offense'?g.ourRoster:g.opponentRoster; $('main').innerHTML=`<div class="live-heading"><div><span class="eyebrow">${g.status==='live'?'Live game':'Game complete'} · ${esc(g.gameDate)}</span><h1>${esc(g.team)} vs. ${esc(g.opponent)}</h1><span class="save-status"><i class="save-dot"></i>Saved on this iPad · revision ${g.revision}${g.transferLocked?' · result exported and locked':''}</span></div><div class="actions">${button('Quick Stats','quick')}${button(g.status==='live'?'Timeout report':'Game report','report','primary')}</div></div>${!ready?'<aside class="note-box">Before relying on offline reopening, go to Games and Prepare for offline, then run the Home Screen airplane-mode test.</aside>':''}<section class="scoreboard"><div><small>${esc(g.team)}</small><strong>${g.finalScore?g.finalScore.our:score.our}</strong><p>${a.offense.possessions} possessions · ${a.offense.ppp==null?'—':a.offense.ppp.toFixed(2)} PPP</p></div><div class="period">${g.status==='completed'?'FINAL':esc(periodName(g))}</div><div><small>${esc(g.opponent)}</small><strong>${g.finalScore?g.finalScore.opponent:score.opponent}</strong><p>${a.defense.possessions} possessions · ${a.defense.ppp==null?'—':a.defense.ppp.toFixed(2)} PPP</p></div></section>${live?`<section class="surface tracker"><div class="tracker-heading"><div><span class="eyebrow">Current possession</span><h3>${d.teamSide==='offense'?'Our offense':'Our defense · opponent ball'}</h3></div><div class="side-switch">${button('Offense','side',d.teamSide==='offense'?'active':'','data-side="offense"')}${button('Defense','side',d.teamSide==='defense'?'active':'','data-side="defense"')}${button('Auto-switch '+(g.autoSwitch?'On':'Off'),'auto')}</div></div><div class="tracking-tags">${M.focusForSide(g).map((t,i)=>{if(t.type==='rightHandDrive'&&d.teamSide!=='defense')return '';const count=t.type==='paintTouch'?d.playEvents.filter(e=>e.type==='paintTouch').length:t.type==='offensiveRebound'?d.offensiveRebounds:0,active=count>0||d[t.type]===true||d.playEvents.some(e=>e.type===t.type&&(t.type!=='customTag'||e.label===t.label));return button(esc(t.label)+(count?' ×'+count:active?' ✓':''),'tag',active?'active':'',`data-index="${i}" aria-pressed="${active}"`);}).join('')||'<p class="muted">Points-only tracking. Choose an outcome below.</p>'}</div><small>Tap Paint touch or OREB for each occurrence. Count a new paint entry or catch, not every dribble.</small>${possessionBar(g)}${freeThrowControls(g)}${!M.hasFreeThrows(d)?`<div class="outcomes">${[0,1,2,3].map(n=>button(String(n),'points','',`data-points="${n}"`)).join('')}${button(d.teamSide==='offense'?'Turnover':'Forced turnover','turnover','danger')}</div>`: ''}<div class="live-bottom"><small>${d.teamSide==='offense'?'Points scored':'Points allowed'} · one outcome finishes one possession</small><div class="actions">${button('Undo tag','undo-tag')}${button('Undo possession','undo-possession')}</div></div><details class="player-credit"><summary>Player credit · optional${d.jersey?' · #'+esc(d.jersey):''}</summary><label>Shot / paint / rebound player #<select id="jerseySelect"><option value="">Team event / manual #</option>${roster.map(p=>`<option value="${esc(p.jersey)}" ${p.jersey===d.jersey?'selected':''}>#${esc(p.jersey)} · ${esc(p.name)}</option>`).join('')}</select></label>${field('Manual jersey #','manualJersey',d.jersey,'text','maxlength="3" inputmode="numeric" pattern="[0-9]{0,3}"')}<small>For deflections, the jersey belongs to the defensive team. Leave blank for team events.</small></details></section>`:`<section class="surface"><h3>${g.transferLocked?'Exported result · locked copy':'The game is saved.'}</h3><p class="field-note">${g.transferLocked?'Import the exported result in CoachIQ. Make later corrections there. You can still view reports and export backups here.':'Open the report to review strengths and concerns, or correct a saved possession before exporting.'}</p><div class="actions">${button('Open game report','report','primary')}${!g.transferLocked?button('Export final result & lock','export-result','mint'):button('Download result again','export-result')}${button('Backup game','backup')}</div></section>`}${review.playerAlerts.length?'<div class="alert-strip">'+review.playerAlerts.map(p=>'<p>'+esc(p.text)+'</p>').join('')+'</div>':''}<details class="tools"><summary>Game tools · reports, adjustments, rosters & backup</summary><div>${live?button('End period & report','period')+button('Mark adjustment','marker')+button('Choose tracking tags','focus')+button('Score-only adjustment','score')+button('Finish game','finish','mint'):''}${button('Review possessions','review')}${button('Correct team for import','relink-team')}${button('Rosters & scouting','scout')}${button('Export backup','backup')}${button('Back to games','home')}</div></details><p class="footer-note">${a.intelligence.kills.total} defensive kills · ${a.intelligence.kills.currentStops} consecutive stops now · longest ${a.intelligence.kills.longestStops}. Local analytics use recorded possessions and credited plays. No internet is needed for these tools.</p>`;}
function guide(){modal('Set up your iPad, one step at a time',`<ol class="guide-steps"><li><strong>Open this link in Safari while online.</strong><p>${location.hostname.endsWith("chatgpt.site")?"Sign in with the same ChatGPT account that owns this private app if asked. This does not sign you into Google or move game data.":"This app saves games in this browser. Open the same Home Screen icon each time; importing a backup is required when changing app addresses."}</p></li><li><strong>Tap Prepare for offline.</strong><p>Wait until the app confirms that the app files and local database are available. If it reports a failure, stop and resolve it before using this for a game.</p></li><li><strong>Add it to your Home Screen.</strong><p>Safari → Share → Add to Home Screen. Open the new icon and prepare again there. Safari and Home Screen storage can behave differently.</p></li><li><strong>Set up a test game.</strong><p>Create a game manually, or import a CoachIQ preparation JSON file with rosters and scouting. Files already on the iPad can be imported offline.</p></li><li><strong>Run the airplane-mode test.</strong><p>Turn Wi-Fi and cellular off. Record possessions, repeated paint touches, rebounds, reports and period changes. Background, lock/unlock, close and reopen from the Home Screen. Confirm that all plays and the unfinished possession are still there.</p></li><li><strong>Export a backup, then finish the test.</strong><p>Confirm the JSON file saved in Files. Finish locally, export the locked final result, reconnect, and import that result in CoachIQ. Re-importing the identical result must not create a duplicate.</p></li></ol><div class="note-box">Use a disposable game for this test. This pilot is not certified for your iPad until you complete those steps. Your current Google-based CoachIQ remains separate and unchanged.</div>`);}
function showNew(prepared=null){const seed=prepared||{},focus=seed.focus||[{type:'paintTouch',label:'Paint touch'},{type:'offensiveRebound',label:'OREB'}];modal('Set up a game',`<form id="newGameForm"><div class="form-grid">${linkedTeamField(seed.team)}${field('Opponent','newOpponent',seed.opponent||'','','required maxlength="80"')}${field('Game date','newDate',seed.gameDate||new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10),'date','required')}<label>Game format<select id="newFormat"><option ${seed.gameFormat!=='Halves'?'selected':''}>Quarters</option><option ${seed.gameFormat==='Halves'?'selected':''}>Halves</option></select></label>${field('Minutes per period','newMinutes',seed.periodLength||8,'number','min="1" max="60" required')}<div></div><label>Our roster · optional<textarea id="newOurRoster" placeholder="12, Player Name\n23, Player Name">${esc((seed.ourRoster||[]).map(p=>p.jersey+', '+p.name).join('\n'))}</textarea></label><label>Opponent roster · optional<textarea id="newOpponentRoster" placeholder="12, Player Name">${esc((seed.opponentRoster||[]).map(p=>p.jersey+', '+p.name).join('\n'))}</textarea></label><div class="wide"><details><summary>What matters tonight · offense &amp; defense</summary>${focusSideFields("new",M.cleanFocusBySide(seed.focusBySide,focus),"offense")}</details></div><div class="wide"><p class="field-note">${seed.scouting?'Scouting notes and watchlist are attached from the preparation file.':'Rosters and game-plan objectives are optional. You can track team events with no player selected.'}</p></div></div><div class="form-footer">${button('Cancel','close')}<button class="primary" type="submit">Save game on this iPad</button></div></form>`);$('newGameForm').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;if(submit?.disabled)return;if(submit)submit.disabled=true;try{const focusBySide=readFocusSides('new'),g=M.createGame({team:$('newTeam').value,opponent:$('newOpponent').value,gameDate:$('newDate').value,gameFormat:$('newFormat').value,periodLength:Number($('newMinutes').value),ourRoster:M.roster($('newOurRoster').value),opponentRoster:M.roster($('newOpponentRoster').value),focus:focusBySide.offense,focusBySide},{...seed,season:seed.season||teamLink?.season||''});current=await putGame(g,0);close();await refresh();toast('Game saved on this iPad.');}catch(e){error(e);}finally{if(submit)submit.disabled=false;}};}
function focusChoices(focus){const custom=focus.filter(t=>t.type==='customTag'),catalog=M.TAGS.map(([type,label])=>({type,label})).concat(custom);return catalog.map(t=>`<label><input type="checkbox" data-tag="${esc(t.type)}" data-label="${esc(t.label)}" ${focus.some(f=>f.type===t.type&&f.label===t.label)?'checked':''}>${esc(t.label)}</label>`).join('');}
function readFocus(container){return M.cleanFocus([...$(container).querySelectorAll('input:checked')].map(e=>({type:e.dataset.tag,label:e.dataset.label})));}
function focusSideFields(prefix,choices,side){return `<div class="actions" style="margin:12px 0">${['offense','defense'].map(s=>button(s==='offense'?'Our offense':'Our defense','focus-edit-side',s===side?'primary':'',`data-prefix="${prefix}" data-side="${s}"`)).join('')}</div>${['offense','defense'].map(s=>`<section id="${prefix}FocusPanel-${s}" data-focus-panel ${s===side?'':'hidden'}><h3>${s==='offense'?'When we have the ball':'When the opponent has the ball'}</h3><p class="field-note">Up to six tags for this side. ${s==='defense'?'Paint touches, rebounds and scoring actions describe the opponent; deflections describe our defense.':'These choices apply only to our offensive possessions.'}</p><div class="check-grid" id="${prefix}FocusChoices-${s}">${focusChoices(choices[s])}</div></section>`).join('')}`;}
function readFocusSides(prefix){return{offense:readFocus(prefix+'FocusChoices-offense'),defense:readFocus(prefix+'FocusChoices-defense')};}
function showFocus(){modal('Choose offense & defense tags',`<form id="focusForm"><p class="field-note">Set each side independently, then save both lists. Finish the current possession first; saved possessions keep their original tracking coverage.</p>${focusSideFields('edit',M.cleanFocusBySide(current.focusBySide,current.focus),current.draft.teamSide)}${field('Custom tag for the selected side','customFocus','','text','maxlength="40"')}${button('Add custom choice','add-custom')}<div class="form-footer"><button class="primary" type="submit">Save offense & defense</button></div></form>`);$('focusForm').onsubmit=async e=>{e.preventDefault();try{const choices=readFocusSides('edit');if(await mutate(g=>M.setFocusBySide(g,choices)))close();}catch(e){toast(e.message);}};}

function quickTiles(){const {analytics:a,score}=M.totals(current),fmt=v=>v==null?'—':v.toFixed(2),tiles=[{id:'score',label:'Tracked score',us:(current.finalScore||score).our,opp:(current.finalScore||score).opponent},{id:'ppp',label:'PPP · scored / allowed',us:fmt(a.offense.ppp),opp:fmt(a.defense.ppp)},{id:'possessions',label:'Possessions',us:a.offense.possessions,opp:a.defense.possessions},{id:'paint',label:'Recorded paint touches',us:a.offense.paintTouches,opp:a.defense.paintTouches},{id:'rebounds',label:'Offensive rebounds',us:a.offense.offensiveRebounds,opp:a.defense.offensiveRebounds},{id:'turnovers',label:'Turnovers',us:a.offense.turnovers,opp:a.defense.forcedTurnovers},{id:'kills',label:'Kills / current defensive stops',us:a.intelligence.kills.total+' / '+a.intelligence.kills.currentStops,opp:'—'},{id:'fouls',label:'Fouls drawn · keeps ball / FTs',us:a.offense.foulsRetained+' / '+a.offense.foulsToFreeThrows,opp:a.defense.foulsRetained+' / '+a.defense.foulsToFreeThrows},{id:'freeThrows',label:'Free throws · made / attempted',us:a.offense.freeThrowsMade+' / '+a.offense.freeThrowsAttempted,opp:a.defense.freeThrowsMade+' / '+a.defense.freeThrowsAttempted},{id:'transition',label:'Transition points',us:a.offense.transitionPoints,opp:a.defense.transitionPoints}];M.focusCatalogForGame(current).forEach(t=>{const matches=side=>a.intelligence.tagPatterns.find(p=>p.side===side&&p.type===t.type&&(t.type!=='customTag'||p.label===t.label));const our=matches('offense'),opp=matches('defense');tiles.push({id:'tag:'+t.type+':'+t.label,label:t.label+' · pts / tagged poss',us:our?our.points+' / '+our.possessions:'0 / 0',opp:opp?opp.points+' / '+opp.possessions:'0 / 0'});});return tiles;}
function showQuick(){const tiles=quickTiles(),ids=current.quickStats.filter(id=>tiles.some(t=>t.id===id));modal('Quick Stats',`<div class="quick-grid">${tiles.filter(t=>ids.includes(t.id)).map(t=>`<article class="quick-tile"><h3>${esc(t.label)}</h3><div class="pair"><span><small>Us</small><strong>${esc(t.us)}</strong></span><span><small>Opponent</small><strong>${esc(t.opp)}</strong></span></div></article>`).join('')}</div><p class="field-note">Game to date. The unfinished possession is excluded. Tag groups overlap; untracked tags are not proof that an action did not happen. Score-only adjustments are excluded from PPP.</p><details><summary>Choose my stats · up to eight</summary><div class="check-grid" id="quickChoices">${tiles.map(t=>`<label><input type="checkbox" value="${esc(t.id)}" ${ids.includes(t.id)?'checked':''}>${esc(t.label)}</label>`).join('')}</div>${button('Save quick card','save-quick','primary')}</details>`,periodName(current)+' · saved locally');}
function list(items,empty){return '<ul>'+(items.length?items:[empty]).map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>';}
function showReport(title='Game report',reportPeriod=current.period){const reportGame={...current,period:reportPeriod},r=M.gameReport(reportGame),a=r.analytics,review=r.review;modal(title,`<div class="report-banner"><small>${esc(current.team)} vs. ${esc(current.opponent)} · ${esc(periodName(reportGame))}</small><h3>${r.score.our} – ${r.score.opponent}</h3><strong>${esc(r.decision.nextAdjustment.title)}</strong><p>${esc(r.decision.nextAdjustment.action)}</p><p><small>${esc(r.decision.nextAdjustment.evidence)} ${esc(r.decision.nextAdjustment.sample)}</small></p></div><div class="quick-grid"><article class="quick-tile"><h3>Our offense</h3><strong>${a.offense.points} points / ${a.offense.possessions} possessions</strong><p class="field-note">${a.offense.ppp==null?'—':a.offense.ppp.toFixed(2)} PPP · ${a.offense.paintTouches} paint touches · ${a.offense.offensiveRebounds} OREB · FT ${a.offense.freeThrowsMade}/${a.offense.freeThrowsAttempted}</p></article><article class="quick-tile"><h3>Our defense</h3><strong>${a.defense.points} allowed / ${a.defense.possessions} possessions</strong><p class="field-note">${a.defense.ppp==null?'—':a.defense.ppp.toFixed(2)} PPP allowed · ${a.intelligence.kills.total} kills · ${a.intelligence.kills.longestStops} longest stop run · Opp FT ${a.defense.freeThrowsMade}/${a.defense.freeThrowsAttempted}</p></article></div><div class="report-columns"><article><h3>Keep doing</h3>${list(review.keepDoing,'No repeatable positive pattern is supported by this sample yet.')}</article><article><h3>Address moving forward</h3>${list(review.address,'No clear concern is supported by the recorded sample yet.')}</article></div>${review.playerAlerts.length?'<h3 class="report-section">Player alerts</h3>'+list(review.playerAlerts.map(p=>p.text),''):''}${r.decision.watchlist.length?'<h3 class="report-section">Scouting watchlist</h3>'+r.decision.watchlist.map(w=>'<article class="report-pattern"><strong>'+esc(w.title||w.label)+'</strong><p>'+esc(w.evidence)+'</p><small>'+esc(w.sample)+'</small></article>').join(''):''}${review.adjustments.length?'<h3 class="report-section">Since the adjustment</h3>'+review.adjustments.map(m=>'<article class="report-pattern"><strong>'+esc(m.label)+'</strong>'+list(m.rows.map(row=>row.text),'')+'<small>'+esc(m.note)+'</small></article>').join(''):''}<details class="report-section"><summary>More tracked patterns</summary>${a.intelligence.insights.map(i=>'<article class="report-pattern"><strong>'+esc(i.title)+'</strong><p>'+esc(i.text)+'</p></article>').join('')}</details>${r.scout?'<details><summary>Scouting plan vs. recorded results</summary><p class="field-note">Scouting notes loaded onto this device. Free-text plans are not automatically graded.</p>'+r.scout.rows.map(row=>'<article class="report-pattern"><strong>'+esc(row.title)+' · '+esc(row.status.replaceAll('_',' '))+'</strong><p>'+esc(row.planned)+'</p><p>'+esc(row.actual)+'</p></article>').join('')+'</details>':''}<details><summary>Player totals</summary><div class="table-wrap"><table><thead><tr><th>Player</th><th>OREB</th><th>Paint</th><th>Deflections</th><th>Points</th><th>FT</th></tr></thead><tbody>${a.playerTotals.map(p=>'<tr><td>'+(p.playerSide==='opponent'?'Opp':'Us')+' #'+esc(p.jersey)+'</td><td>'+p.offensiveRebounds+'</td><td>'+p.paintTouches+'</td><td>'+p.deflections+'</td><td>'+p.points+'</td><td>'+p.freeThrowsMade+'/'+p.freeThrowsAttempted+'</td></tr>').join('')}</tbody></table></div></details><p class="field-note">${esc(review.coverage)}</p>${current.finalScore&&(current.finalScore.our!==a.offense.points||current.finalScore.opponent!==a.defense.points)?'<p class="field-note">Confirmed final score can differ from recorded-possession points because of corrections, score-only adjustments or missing possessions. Editing a possession does not change the confirmed final score.</p>':''}<div class="form-footer no-print">${button('Review possessions','review')}${button('Print / save PDF','print')}${button('Back to tracking','close','primary')}</div>`,current.status==='completed'?'Postgame · saved on this iPad':'Timeout / period · local analysis');}
function showReview(){const entries=M.activeLog(current).map((p,i)=>({p,i})).filter(e=>logSide==='all'||e.p.teamSide===logSide),pages=Math.max(1,Math.ceil(entries.length/10));logPage=Math.min(logPage,pages-1);modal('Review possessions',`<div class="log-toolbar">${['all','offense','defense'].map(s=>button(s==='all'?'Timeline':s==='offense'?'Offense':'Defense','log-side',logSide===s?'primary':'',`data-side="${s}"`)).join('')}</div><p class="field-note">${entries.length} possessions · page ${logPage+1} of ${pages}</p>${entries.slice(logPage*10,logPage*10+10).map(({p,i})=>`<article class="possession-row ${p.teamSide}"><strong>${p.teamSide==='offense'?'Offense':'Defense'} · game possession ${i+1} · period ${p.period} · ${p.points} points${p.turnover||p.forcedTurnover?' · turnover':''}</strong><p>${esc(draftDescription(p))}</p>${p.revision?'<small>Corrected · revision '+p.revision+'</small>':''}${current.transferLocked?'':button('Edit possession','edit','',`data-id="${esc(p.possessionId)}"`)}</article>`).join('')||'<p class="field-note">No possessions in this view yet.</p>'}<div class="form-footer">${logPage?button('Previous','log-prev'):''}${logPage+1<pages?button('Next','log-next'):''}${button('Close','close','primary')}</div>`);}
function showMarker(){modal('Mark a coaching adjustment',`<form id="markerForm">${field('Adjustment','markerLabel','','text','required maxlength="80" list="markerNames" placeholder="Switched to 2–3 zone"')}<datalist id="markerNames"><option value="Switched to 2–3 zone"></option><option value="Started pressing"></option><option value="Switching ball screens"></option></datalist><label>Compare<select id="markerSide"><option value="defense">Our defense</option><option value="offense">Our offense</option><option value="both">Both</option></select></label><p class="field-note">Reports compare the last ten recorded possessions before this point with possessions afterward, ending at the next marker. This does not prove the adjustment caused a change.</p><div class="form-footer"><button class="primary" type="submit">Mark now on this iPad</button></div></form>`);$('markerForm').onsubmit=async e=>{e.preventDefault();const label=$('markerLabel').value,side=$('markerSide').value;if(await mutate(g=>M.addMarker(g,label,side)))close();};}
function showFinish(){const {score}=M.totals(current);modal('Finish and save this game',`<form id="finishForm"><p class="field-note">Confirm the final score. The game is saved locally; no internet is required. You can review corrections before exporting the locked result.</p><div class="form-grid">${field('Our final score','finalOur',score.our,'number','min="0" required')}${field('Opponent final score','finalOpponent',score.opponent,'number','min="0" required')}</div><div class="form-footer"><button class="mint" type="submit">Finish on this iPad</button></div></form>`);$('finishForm').onsubmit=async e=>{e.preventDefault();const our=Number($('finalOur').value),opp=Number($('finalOpponent').value);if(await mutate(g=>M.finishGame(g,our,opp))){close();showReport('Postgame report');}};}
function showScore(){modal('Score-only adjustment',`<form id="scoreForm"><label>Team<select id="scoreSide"><option value="our">Our team</option><option value="opponent">Opponent</option></select></label>${field('Points to add or subtract','scoreDelta',1,'number','min="-10" max="10" required')}${field('Reason','scoreReason','','text','required maxlength="120" placeholder="Technical free throw / scoreboard correction"')}<p class="field-note">Changes the tracked score. Does not add a possession or change possession PPP.</p><div class="form-footer"><button class="primary" type="submit">Save adjustment</button></div></form>`);$('scoreForm').onsubmit=async e=>{e.preventDefault();const side=$('scoreSide').value,delta=Number($('scoreDelta').value),reason=$('scoreReason').value;if(await mutate(g=>{if(!Number.isInteger(delta)||!delta||Math.abs(delta)>10)throw Error('Choose a non-zero adjustment from −10 to 10.');if(!reason.trim())throw Error('Enter a reason.');g.scoreAdjustments.push({id:M.id('SCORE-'),side,delta,reason:reason.trim().slice(0,120),period:g.period,at:new Date().toISOString()});}))close();};}
function showScout(){modal('Rosters & scouting',`<div class="report-columns">${[['Our roster',current.ourRoster],['Opponent roster',current.opponentRoster]].map(([title,players])=>'<article><h3>'+title+'</h3>'+list(players.map(p=>'#'+p.jersey+' · '+p.name),'No roster loaded. Team events remain available.')+'</article>').join('')}</div>${current.scouting?'<h3>Opponent identity</h3><p class="field-note">'+esc(current.scouting.identity||'Not specified')+'</p><h3>Keys to victory</h3><p class="field-note">'+esc(current.scouting.keysToVictory||'Not specified')+'</p>'+(current.scouting.sections||[]).map(s=>'<details><summary>'+esc(s.title)+'</summary><p class="field-note" style="white-space:pre-wrap">'+esc(s.content)+'</p></details>').join(''):'<p class="field-note">No scouting report is attached. Import a CoachIQ preparation file when creating the next game to keep those notes available offline.</p>'}`);}
function showEditor(pid){const p=current.possessions.find(p=>p.possessionId===pid&&!p.voided);if(!p)return;editor=M.clone(p);modal('Correct a saved possession',`<form id="editForm"><p class="field-note">${p.teamSide==='defense'?'Defensive':'Offensive'} possession · original sequence ${p.sequence}. A reason and before/after history are saved locally.</p><div class="form-grid">${field('Points','editPoints',p.points,'number','min="0" max="20" required')}${field('Period','editPeriod',p.period,'number','min="1" max="20" required')}${field('Scorer # · optional','editScorer',p.playEvents.find(e=>/^made[123]$/.test(e.type))?.jersey||'','text','maxlength="3" inputmode="numeric" pattern="[0-9]{0,3}"')}</div><div class="editor-flags"><label><input id="editTransition" type="checkbox" ${p.transition?'checked':''}>Transition</label><label><input id="editRight" type="checkbox" ${p.rightHandDrive?'checked':''} ${p.teamSide!=='defense'?'disabled':''}>Right-hand drive allowed</label><label><input id="editTurnover" type="checkbox" ${p.turnover||p.forcedTurnover?'checked':''}>Turnover / forced turnover</label></div><h3>Plays and player credit</h3><p class="field-note">Add one play for every paint touch, rebound or free-throw attempt. For FT possessions, Points must match made FTs plus any made baskets. Deflection jerseys belong to the defensive team; shot/touch/rebound jerseys belong to the offensive team.</p><div id="editorEvents"></div>${button('Add play','edit-add')}${field('Correction reason','editReason','','text','required maxlength="240"')}<details><summary>Correction history</summary>${current.corrections.filter(c=>c.possessionId===pid).map(c=>'<p class="field-note">'+esc(c.at)+' · '+esc(c.reason)+' · '+Number(c.before?.points||0)+' → '+Number(c.after?.points||0)+' points</p>').join('')||'<p class="field-note">No previous corrections.</p>'}</details><div class="form-footer"><button class="primary" type="submit">Save correction on this iPad</button></div></form>`);if(!M.hasFreeThrows(editor))editor.playEvents=editor.playEvents.filter(e=>!/^made[123]$/.test(e.type));renderEditorEvents();$('editForm').onsubmit=async e=>{e.preventDefault();const data=M.clone(editor),reason=$('editReason').value;data.points=Number($('editPoints').value);data.period=Number($('editPeriod').value);data.transition=$('editTransition').checked;data.rightHandDrive=$('editRight').checked;data.turnover=data.teamSide==='offense'&&$('editTurnover').checked;data.forcedTurnover=data.teamSide==='defense'&&$('editTurnover').checked;data.paintTouch=data.playEvents.some(e=>e.type==='paintTouch');data.offensiveRebounds=data.playEvents.filter(e=>e.type==='offensiveRebound').length;if(!M.hasFreeThrows(data)&&data.points>0&&!data.playEvents.some(e=>/^made[123]$/.test(e.type)))data.playEvents.push({type:'made'+data.points,jersey:$('editScorer').value});if(await mutate(g=>M.correctPossession(g,pid,data,reason))){close();showReview();}};}
function renderEditorEvents(){if(!editor)return;const types=M.TAGS.filter(t=>!['transition','rightHandDrive'].includes(t[0])).concat([['miss2','Missed 2'],['miss3','Missed 3'],['andOne','And-one'],['foulRetained','Foul · keeps ball'],['foulFreeThrows','Foul → FTs'],['freeThrows','Free throws'],['ftMade','FT made'],['ftMiss','FT missed'],['made2','Made 2'],['made3','Made 3'],['customTag','Custom tag']]);$('editorEvents').innerHTML=editor.playEvents.map((e,i)=>`<div class="edit-event"><label>Play<select data-edit="type" data-index="${i}">${types.map(([type,label])=>`<option value="${type}" ${e.type===type?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>Player #<input data-edit="jersey" data-index="${i}" value="${esc(e.jersey||'')}" maxlength="3" inputmode="numeric"></label>${e.type==='customTag'?`<label>Tag name<input data-edit="label" data-index="${i}" value="${esc(e.label||'')}" maxlength="40"></label>`:'<span></span>'}${button('Remove','edit-remove','',`data-index="${i}"`)}</div>`).join('');}
async function importFile(file){if(file.size>8*1024*1024)throw Error('Choose a JSON file smaller than 8 MB.');const value=JSON.parse(await file.text());if(value.format==='coachiq-team-link'){teamLink=await putTeamLink(M.cleanTeamLink(value));close();await refresh();toast('CoachIQ team names linked. New games now use an exact-name dropdown.');return;}if(value.format==='coachiq-offline-preparation'&&value.schema===1){const teams=[...new Set([...(teamLink?.teams||[]),value.team])];teamLink=await putTeamLink(M.cleanTeamLink({format:'coachiq-team-link',schema:1,teams,season:value.season||teamLink?.season||'',schoolName:teamLink?.schoolName||''}));showNew(value);return;}const candidates=value.format==='coachiq-offline-library'?value.games:[value];if(!Array.isArray(candidates)||candidates.length>100)throw Error('Unsupported backup file.');const validated=candidates.map(x=>M.validateImportedGame(x));let imported=0;for(const g of validated){if(await getGame(g.id))continue;const saved=await putGame({...g,revision:0},0);current=saved;imported++;}await refresh();toast(imported?imported+' game(s) restored on this iPad.':'These game IDs are already saved here. Nothing was overwritten.');}
let preparing=false;
function preparationMessage(message,state='working'){const panel=$('preparationStatus');panel.hidden=false;panel.dataset.state=state;panel.textContent=message;document.querySelectorAll('[data-action="prepare"]').forEach(button=>{button.disabled=preparing;button.textContent=preparing?'Preparing…':ready?'Check again':'Prepare for offline';});}
async function prepare(){if(preparing)return;preparing=true;ready=false;preparationMessage('Starting offline setup…');try{await prepareOffline({openDB,serviceWorker:navigator.serviceWorker,storage:navigator.storage,uuid:()=>crypto.randomUUID(),MessageChannel,version:M.VERSION,onProgress:preparationMessage});ready=true;preparing=false;render();preparationMessage('Offline files and device storage verified. Next: Add to Home Screen, open that icon, and run the airplane-mode close/reopen test.','success');toast('Offline setup checked. Your iPad still needs the airplane-mode test.');}catch(e){ready=false;preparing=false;render();const hint=window.self!==window.top?' Open the link directly in Safari, outside this app.':'';preparationMessage('Offline setup failed: '+e.message+hint,'error');toast('Offline setup did not complete. See the message above.');}}

async function exportResult(){if(current.status!=='completed')throw Error('Finish the game first.');if(!current.transferLocked){modal('Export and lock this result',`<p>Export creates a stable final result for CoachIQ. After locking, make further corrections in CoachIQ after import. Your local game and reports remain available.</p><div class="form-footer">${button('Cancel','close')}${button('Lock & download result','confirm-export','primary')}</div>`);return;}download(current,'CoachIQ-result-'+current.id+'.json');}
$('homeButton').onclick=async()=>{await work;current=null;await refresh();};$('guideButton').onclick=guide;$('importFile').onchange=async e=>{try{if(e.target.files[0])await importFile(e.target.files[0]);}catch(e){toast(e.message);}e.target.value='';};
document.addEventListener('click',async e=>{const b=e.target.closest('button[data-action],button[data-close]');if(!b)return;if(b.hasAttribute('data-close')){close();return;}const action=b.dataset.action;try{if(action==='close'){close();return;}if(action==='import'){$('importFile').click();return;}if(action==='focus-edit-side'){const prefix=b.dataset.prefix,side=b.dataset.side;['offense','defense'].forEach(s=>$(prefix+'FocusPanel-'+s).hidden=s!==side);document.querySelectorAll('[data-action="focus-edit-side"][data-prefix="'+prefix+'"]').forEach(el=>el.classList.toggle('primary',el.dataset.side===side));return;}if(action==='team-link'){showTeamLink();return;}if(action==='new'){showNew();return;}if(action==='prepare'){await prepare();return;}if(action==='delete-backup'){const game=await getGame(b.dataset.id);if(!game)throw Error('This game is no longer saved here.');download(game,'CoachIQ-backup-'+game.id+'.json');return;}if(action==='delete-game'){await showDeleteGame(b.dataset.id);return;}if(action==='open'){current=await getGame(b.dataset.id);render();if(current.status==='completed')showReport('Postgame report');return;}if(action==='home'){await work;current=null;close();await refresh();return;}if(!current&&action!=='add-custom')return;
if(action==='foul-retained'||action==='foul-fts'){const outcome=action==='foul-retained'?'retained':'freeThrows';await mutate(g=>M.recordFoul(g,outcome));}
else if(action==='ft-start')await mutate(M.startFreeThrows);
else if(action==='ft-made'||action==='ft-missed'){const made=action==='ft-made';await mutate(g=>M.recordFreeThrow(g,made));}
else if(action==='ft-basket'){const points=Number(b.dataset.points);await mutate(g=>M.addFreeThrowBasket(g,points));}
else if(action==='ft-finish'){const draftId=current.draft.id;await mutate(g=>M.finishFreeThrows(g,draftId));}
else if(action==='tag'){const tag=M.clone(M.focusForSide(current)[Number(b.dataset.index)]);await mutate(g=>M.tapTag(g,tag));}
else if(action==='points'||action==='turnover'){const draftId=current.draft.id,points=Number(b.dataset.points||0);await mutate(g=>M.finishPossession(g,points,action==='turnover',draftId));}
else if(action==='undo-tag')await mutate(M.undoDraft);
else if(action==='undo-possession'){modal('Undo latest possession?',`<p>The latest recorded possession will be marked undone. Its original events remain in the local audit history.</p><div class="form-footer">${button('Cancel','close')}${button('Undo possession','confirm-undo','danger')}</div>`);}
else if(action==='confirm-undo'){if(await mutate(M.undoPossession))close();}
else if(action==='side'){const side=b.dataset.side;await mutate(g=>M.switchSide(g,side));}
else if(action==='auto')await mutate(g=>{g.autoSwitch=!g.autoSwitch;});
else if(action==='quick'){await work;showQuick();}
else if(action==='report'){await work;showReport(current.status==='completed'?'Postgame report':'Timeout report');}
else if(action==='review'){await work;logPage=0;showReview();}
else if(action==='log-side'){logSide=b.dataset.side;logPage=0;showReview();}
else if(action==='log-prev'){logPage--;showReview();}else if(action==='log-next'){logPage++;showReview();}
else if(action==='edit')showEditor(b.dataset.id);
else if(action==='edit-add'){if(editor.playEvents.length>=99)throw Error('Maximum play count reached.');editor.playEvents.push({type:'paintTouch',jersey:''});renderEditorEvents();}
else if(action==='edit-remove'){editor.playEvents.splice(Number(b.dataset.index),1);renderEditorEvents();}
else if(action==='period'){const period=current.period,name=periodName(current);if(await mutate(M.advancePeriod))showReport(name+' report',period);}
else if(action==='marker')showMarker();else if(action==='finish')showFinish();else if(action==='focus')showFocus();else if(action==='score')showScore();else if(action==='scout')showScout();else if(action==='relink-team')showRelinkTeam();
else if(action==='backup'){await work;download(current,'CoachIQ-backup-'+current.id+'.json');}
else if(action==='export-result')await exportResult();
else if(action==='confirm-export'){if(await mutate(g=>{g.transferLocked=true;g.exportedAt=new Date().toISOString();})){close();download(current,'CoachIQ-result-'+current.id+'.json');}}
else if(action==='print'){prepareReportPrint();window.print();}
else if(action==='save-quick'){const ids=[...$('quickChoices').querySelectorAll('input:checked')].map(e=>e.value);if(!ids.length||ids.length>8)throw Error('Choose between one and eight quick stats.');if(await mutate(g=>{g.quickStats=ids;}))showQuick();}
else if(action==='add-custom'){const label=$('customFocus').value.trim();if(!label||label.length>40)throw Error('Enter a custom tag name of 1–40 characters.');const row=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.tag='customTag';input.dataset.label=label;input.checked=true;row.append(input,document.createTextNode(label));const panel=document.querySelector('[data-focus-panel]:not([hidden])');panel.querySelector('.check-grid').append(row);$('customFocus').value='';}
}catch(e){toast(e.message);}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-edit]')){editor.playEvents[Number(e.target.dataset.index)][e.target.dataset.edit]=e.target.value;if(e.target.dataset.edit==='type')renderEditorEvents();return;}if(e.target.id==='jerseySelect'||e.target.id==='manualJersey'){const jersey=e.target.value.trim();await mutate(g=>{if(jersey&&!/^\d{1,3}$/.test(jersey))throw Error('Use a jersey number of 1–3 digits.');g.draft.jersey=jersey;});}});
window.addEventListener('online',status);window.addEventListener('offline',status);window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')status();});
(async()=>{try{await openDB();games=await listGames();teamLink=await getTeamLink();render();if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.getRegistration();if(registration?.active){const c=new MessageChannel();c.port1.onmessage=e=>{ready=e.data.ready===true;render();};registration.active.postMessage({type:'VERIFY_CACHE'},[c.port2]);}}}catch(e){error(e);$('main').innerHTML='<section class="surface empty"><h2>This browser could not open local storage.</h2><p>Use normal Safari browsing, not a private tab. Do not use this app for a game until local storage and offline preparation pass.</p></section>';}})();

window.addEventListener('beforeprint',()=>prepareReportPrint());window.addEventListener('afterprint',()=>clearReportPrint());

function linkedTeamField(selected){if(!teamLink)return field('Our team','newTeam',selected||'','text','required maxlength="200"')+'<p class="field-note">Link CoachIQ teams before exporting this game. Manually typed names must match CoachIQ settings exactly.</p>';return '<label>Our team · linked from CoachIQ<select id="newTeam" required>'+teamLink.teams.map(team=>'<option value="'+esc(team)+'" '+(team===selected?'selected':'')+'>'+esc(team)+'</option>').join('')+'</select></label>';}
function showTeamLink(){modal('Link your CoachIQ teams',`<ol class="guide-steps"><li>In your original CoachIQ app, open Live Game and choose <strong>Download team link</strong>.</li><li>Save <strong>CoachIQ-team-link.json</strong> to Files.</li><li>Import that file here. New games will offer a dropdown with the exact names and carry the linked season.</li></ol><p class="field-note">You can also import a fresh CoachIQ game preparation file to link that setup’s team. This copies settings onto this iPad; it does not automatically sync games.</p>${teamLink?'<p class="field-note">Currently linked: '+teamLink.teams.map(esc).join(' · ')+'</p>':''}<div class="form-footer">${button('Import team-link file','import','primary')}</div>`);}
function showRelinkTeam(){if(!teamLink){showTeamLink();return;}const sourceId=current.id;modal('Correct team for import',`<form id="relinkForm"><p class="field-note">Current team: <strong>${esc(current.team)}</strong>. Choose the matching CoachIQ team. This creates a separate corrected copy with the same score, possessions and reports. The original stays intact.</p>${linkedTeamField(current.team)}<p class="field-note">Linked season: ${esc(teamLink.season||'unspecified')}. Only use this for a game that has not been imported successfully. If it is already in CoachIQ, make corrections there rather than importing another copy.</p><div class="form-footer">${button('Cancel','close')}<button class="primary" type="submit">Save corrected team copy</button></div></form>`);$('relinkForm').onsubmit=async event=>{event.preventDefault();const submit=event.submitter,team=$('newTeam').value;if(submit?.disabled)return;if(submit)submit.disabled=true;try{await work;if(current.id!==sourceId)throw Error('Reopen the game before correcting its team.');const copy=M.copyWithLinkedTeam(current,teamLink,team);current=await putGame(copy,0);close();await refresh();toast('Corrected copy saved. Export its result and use that new JSON file in CoachIQ.');}catch(error){toast(error.message);}finally{if(submit)submit.disabled=false;}};}

async function showDeleteGame(id){await work;const game=await getGame(id);if(!game){await refresh();toast('This game is no longer saved here.');return;}modal('Delete this local game?',`<h3>${esc(game.team)} vs. ${esc(game.opponent)}</h3><p class="field-note">${esc(game.gameDate)} · ${game.status==='live'?'LIVE · unfinished game':game.transferLocked?'Finished and exported':'Finished game'}</p><p>This removes this game's possessions, unfinished draft and reports from GameDay on this iPad. It cannot be undone here. Any CoachIQ import and JSON files already saved in Files remain intact.</p><p class="field-note">${game.status==='live'?'This game is still live. Confirm that this is the game you want to remove.':'Keep an exported backup first if you may want this game later.'}</p><div class="form-footer delete-game-actions">${button('Cancel','close')}${button('Export backup first','delete-backup','',`data-id="${esc(game.id)}"`)}<button id="deleteLocalGameConfirm" class="danger" type="button">Delete from this iPad</button></div>`);$('deleteLocalGameConfirm').onclick=async event=>{const button=event.currentTarget;if(button.disabled)return;button.disabled=true;let completed=false;try{const deleted=await deleteGame(game.id,game.revision);completed=true;if(current?.id===game.id)current=null;close();await refresh();toast(deleted?'Game deleted from this iPad.':'This game was already removed.');}catch(error){toast(completed?'The local game is removed. Reopen Games to refresh the list.':'Game not deleted: '+error.message);button.disabled=false;}};}
